/**
 * What a workout changed about the routine it started from
 * (docs/decisions/ROUTINE-CHANGES.md). One copy for app, edge and web, so
 * the finish prompt, Ask and MCP describe the same change the same way.
 *
 * Rules:
 * - An exercise skipped for today is never a change; it is still in the
 *   routine. Neither is a set left open: only sets added or deleted count.
 * - Warm-up and drop sets are per-day extras and never change set counts.
 * - Rest is a tweak: it updates the routine without asking. Exercises
 *   added, removed or reordered and set counts are structural: the user
 *   picks update, keep or save as new.
 */

/** One routine row as the routine has it now. */
export interface RoutineSlot {
  exerciseId: number;
  name: string;
  sets: number;
  restSeconds: number;
}

/** One exercise as the workout has it at finish, in screen order. */
export interface SessionSlot {
  exerciseId: number;
  name: string;
  /** Live working + failure set rows (done or still open). */
  workingSets: number;
  /** Mean reps over those rows; seeds the rep range of an added exercise. */
  avgReps: number;
  /** The exercise's rest in this workout; null when the session never set one. */
  restSeconds: number | null;
  skipped: boolean;
}

export type RoutineChange =
  | { kind: 'added'; exerciseId: number; name: string; sets: number }
  | { kind: 'removed'; exerciseId: number; name: string }
  | { kind: 'sets'; exerciseId: number; name: string; from: number; to: number }
  | { kind: 'rest'; exerciseId: number; name: string; from: number; to: number }
  | { kind: 'order' };

export interface SessionRoutineDiff {
  changes: RoutineChange[];
  /** True when anything beyond rest changed: the finish prompt asks. */
  structural: boolean;
}

export const NO_ROUTINE_CHANGES: SessionRoutineDiff = { changes: [], structural: false };

const COUNTED_SET_TYPES = new Set(['working', 'failure']);

/** Whether a set row counts toward an exercise's routine set count. */
export function countsAsRoutineSet(setType: string | null | undefined): boolean {
  return COUNTED_SET_TYPES.has(setType ?? 'working');
}

export function diffSessionAgainstRoutine(
  routine: readonly RoutineSlot[],
  session: readonly SessionSlot[],
): SessionRoutineDiff {
  const changes: RoutineChange[] = [];
  const inSession = new Map(session.map((s) => [s.exerciseId, s]));
  const inRoutine = new Map(routine.map((r) => [r.exerciseId, r]));

  for (const s of session) {
    if (inRoutine.has(s.exerciseId) || s.skipped || s.workingSets === 0) continue;
    changes.push({ kind: 'added', exerciseId: s.exerciseId, name: s.name, sets: s.workingSets });
  }
  for (const r of routine) {
    if (!inSession.has(r.exerciseId)) {
      changes.push({ kind: 'removed', exerciseId: r.exerciseId, name: r.name });
    }
  }
  for (const r of routine) {
    const s = inSession.get(r.exerciseId);
    if (!s || s.skipped) continue;
    if (s.workingSets > 0 && s.workingSets !== r.sets) {
      changes.push({ kind: 'sets', exerciseId: r.exerciseId, name: r.name, from: r.sets, to: s.workingSets });
    }
  }
  const sharedSession = session.filter((s) => inRoutine.has(s.exerciseId)).map((s) => s.exerciseId);
  const sharedRoutine = routine.filter((r) => inSession.has(r.exerciseId)).map((r) => r.exerciseId);
  if (sharedSession.some((id, i) => id !== sharedRoutine[i])) changes.push({ kind: 'order' });

  const structural = changes.length > 0;
  for (const r of routine) {
    const s = inSession.get(r.exerciseId);
    if (!s || s.skipped || s.restSeconds == null || s.restSeconds === r.restSeconds) continue;
    changes.push({ kind: 'rest', exerciseId: r.exerciseId, name: r.name, from: r.restSeconds, to: s.restSeconds });
  }
  return { changes, structural };
}

/** The routine's next rows: workout order, added exercises in place, skipped ones kept. */
export interface NextRoutineRow {
  exerciseId: number;
  sets: number;
  /** Only for added exercises; kept rows keep their rep range. */
  repsMin?: number;
  repsMax?: number;
  restSeconds: number;
}

export function nextRoutineRows(
  routine: readonly RoutineSlot[],
  session: readonly SessionSlot[],
  diff: SessionRoutineDiff,
  defaultRestSeconds: number,
): NextRoutineRow[] {
  const removed = new Set(diff.changes.flatMap((c) => (c.kind === 'removed' ? [c.exerciseId] : [])));
  const added = new Set(diff.changes.flatMap((c) => (c.kind === 'added' ? [c.exerciseId] : [])));
  const inRoutine = new Map(routine.map((r) => [r.exerciseId, r]));
  const rows: NextRoutineRow[] = [];
  for (const s of session) {
    const r = inRoutine.get(s.exerciseId);
    if (r) {
      const counted = !s.skipped && s.workingSets > 0;
      rows.push({
        exerciseId: r.exerciseId,
        sets: counted ? s.workingSets : r.sets,
        restSeconds: !s.skipped && s.restSeconds != null ? s.restSeconds : r.restSeconds,
      });
    } else if (added.has(s.exerciseId)) {
      const reps = Math.max(1, Math.round(s.avgReps) || 8);
      rows.push({
        exerciseId: s.exerciseId,
        sets: s.workingSets,
        repsMin: Math.max(1, reps - 2),
        repsMax: reps + 2,
        restSeconds: s.restSeconds ?? defaultRestSeconds,
      });
    }
  }
  // A routine exercise the workout never had (and wasn't removed) can't
  // happen today, but if it does it keeps its place at the end, never lost.
  for (const r of routine) {
    if (!removed.has(r.exerciseId) && !rows.some((x) => x.exerciseId === r.exerciseId)) {
      rows.push({ exerciseId: r.exerciseId, sets: r.sets, restSeconds: r.restSeconds });
    }
  }
  return rows;
}

function formatRest(seconds: number): string {
  if (seconds <= 0) return 'off';
  if (seconds < 60) return `${seconds}s`;
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return s === 0 ? `${m} min` : `${m}:${String(s).padStart(2, '0')}`;
}

function plural(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`;
}

/** One line per change, e.g. "Added Incline DB Press (3 sets)". */
export function describeRoutineChange(change: RoutineChange): string {
  switch (change.kind) {
    case 'added':
      return `Added ${change.name} (${plural(change.sets, 'set')})`;
    case 'removed':
      return `Removed ${change.name}`;
    case 'sets':
      return `${change.name}: ${plural(change.to, 'set')} (was ${change.from})`;
    case 'rest':
      return `${change.name}: rest ${formatRest(change.to)} (was ${formatRest(change.from)})`;
    case 'order':
      return 'New exercise order';
  }
}
